"""Protobuf <-> domain mapping for the Source Bus contract.

Lives in ``outbound/`` because it touches generated stubs. The rest of the SDK
(domain, service, port) never imports ``pb2``.
"""

from __future__ import annotations

from loop_sdk.gen.v1 import source_ingest_pb2 as pb2
from loop_sdk.source.domain.camera import (
    CameraFrameEncoding,
    CameraOpenResult,
    CameraPixelFormat,
    CameraResolution,
    CameraSetting,
    CameraStreamSchema,
    RtspCameraProtocol,
    RtspTransport,
    ZmqCameraProtocol,
    ZmqMessageMode,
)
from loop_sdk.source.domain.config import RobotConfig, RobotConfigOptions
from loop_sdk.source.domain.frame import (
    FrameSample,
    MarkerFrame,
    PolicyActionFrame,
    RobotFrame,
    RobotStateValue,
    TactileChannelValue,
    TactileFrame,
)
from loop_sdk.source.domain.schema import (
    ChannelRole,
    ChannelSpec,
    MarkerStreamSchema,
    RobotStreamSchema,
    RotationType,
    SourceSchema,
    TactileStreamSchema,
)

# Domain closed-enum -> proto enum. None/omitted maps to the proto's UNSPECIFIED.
_ROLE_TO_PB = {
    ChannelRole.CORE: pb2.CHANNEL_ROLE_CORE,
    ChannelRole.AUX: pb2.CHANNEL_ROLE_AUX,
}
_ROT_TO_PB = {
    RotationType.QUATERNION: pb2.ROBOT_ROTATION_TYPE_QUATERNION,
    RotationType.EULER: pb2.ROBOT_ROTATION_TYPE_EULER,
    RotationType.ROTATION_6D: pb2.ROBOT_ROTATION_TYPE_ROTATION_6D,
}
_RTSP_TRANSPORT_TO_PB = {
    RtspTransport.TCP: pb2.RTSP_TRANSPORT_TCP,
    RtspTransport.UDP: pb2.RTSP_TRANSPORT_UDP,
}
_RTSP_TRANSPORT_FROM_PB = {
    pb2.RTSP_TRANSPORT_TCP: RtspTransport.TCP,
    pb2.RTSP_TRANSPORT_UDP: RtspTransport.UDP,
}
_ZMQ_MESSAGE_MODE_TO_PB = {
    ZmqMessageMode.SINGLE_FRAME: pb2.ZMQ_MESSAGE_MODE_SINGLE_FRAME,
}
_ZMQ_MESSAGE_MODE_FROM_PB = {
    pb2.ZMQ_MESSAGE_MODE_UNSPECIFIED: ZmqMessageMode.SINGLE_FRAME,
    pb2.ZMQ_MESSAGE_MODE_SINGLE_FRAME: ZmqMessageMode.SINGLE_FRAME,
}
_CAMERA_FRAME_ENCODING_TO_PB = {
    CameraFrameEncoding.JPEG: pb2.CAMERA_FRAME_ENCODING_JPEG,
}
_CAMERA_FRAME_ENCODING_FROM_PB = {
    pb2.CAMERA_FRAME_ENCODING_UNSPECIFIED: CameraFrameEncoding.JPEG,
    pb2.CAMERA_FRAME_ENCODING_JPEG: CameraFrameEncoding.JPEG,
}
_CAMERA_PIXEL_FORMAT_TO_PB: dict[CameraPixelFormat, pb2.CameraPixelFormat] = {
    CameraPixelFormat.MJPEG: pb2.CAMERA_PIXEL_FORMAT_MJPEG,
}
_CAMERA_PIXEL_FORMAT_FROM_PB: dict[pb2.CameraPixelFormat, CameraPixelFormat] = {
    pb2.CAMERA_PIXEL_FORMAT_UNSPECIFIED: CameraPixelFormat.MJPEG,
    pb2.CAMERA_PIXEL_FORMAT_MJPEG: CameraPixelFormat.MJPEG,
}


def source_declared(schema: SourceSchema, client_version: str) -> pb2.SourceDeclared:
    """Build the initial ``SourceDeclared`` registration message."""
    stream = schema.stream
    if isinstance(stream, RobotStreamSchema):
        return _robot_declared(stream, client_version)
    if isinstance(stream, TactileStreamSchema):
        return _tactile_declared(stream, client_version)
    if isinstance(stream, MarkerStreamSchema):
        return _marker_declared(stream, client_version)
    if isinstance(stream, CameraStreamSchema):
        return _camera_declared(stream, client_version)
    raise TypeError(f"unsupported source schema: {type(stream).__name__}")


def _robot_channel(channel: ChannelSpec) -> pb2.RobotChannelDescriptor:
    descriptor = pb2.RobotChannelDescriptor(
        key=channel.key, label=channel.label, unit=channel.unit, group=channel.group
    )
    if channel.role is not None:
        descriptor.role = _ROLE_TO_PB[channel.role]
    if channel.rot_type is not None:
        descriptor.rot_type = _ROT_TO_PB[channel.rot_type]
    if channel.range is not None:
        descriptor.range.extend(channel.range)
    return descriptor


def _robot_declared(stream: RobotStreamSchema, client_version: str) -> pb2.SourceDeclared:
    message = pb2.SourceDeclared(source_key=stream.source_key, name=stream.name, client_version=client_version)
    message.robot.channels.extend(_robot_channel(channel) for channel in stream.channels)
    message.robot.available_options.CopyFrom(_robot_config_options(stream.available_options))
    return message


def _robot_config_options(options: RobotConfigOptions) -> pb2.RobotConfigOptions:
    return pb2.RobotConfigOptions(
        control_hz=options.control_hz,
        action_space=options.action_space,
        gripper_type=options.gripper_type,
        finger_type=options.finger_type,
        robot_type=options.robot_type,
        robot_firmware_version=options.robot_firmware_version,
        teleoperation_version=options.teleoperation_version,
    )


def robot_config_to_pb(config: RobotConfig) -> pb2.RobotConfig:
    # control_hz/action_space are always set; the optional identity fields are
    # set only when non-empty so an unset proto `optional` stays absent.
    message = pb2.RobotConfig(control_hz=config.control_hz, action_space=config.action_space)
    if config.gripper_type:
        message.gripper_type = config.gripper_type
    if config.finger_type:
        message.finger_type = config.finger_type
    if config.robot_type:
        message.robot_type = config.robot_type
    if config.robot_firmware_version:
        message.robot_firmware_version = config.robot_firmware_version
    if config.teleoperation_version:
        message.teleoperation_version = config.teleoperation_version
    return message


def robot_config_from_pb(message: pb2.RobotConfig) -> RobotConfig:
    # Unset proto `optional string` reads back as "" — the domain default.
    return RobotConfig(
        control_hz=message.control_hz,
        action_space=message.action_space,
        gripper_type=message.gripper_type,
        finger_type=message.finger_type,
        robot_type=message.robot_type,
        robot_firmware_version=message.robot_firmware_version,
        teleoperation_version=message.teleoperation_version,
    )


def _tactile_declared(stream: TactileStreamSchema, client_version: str) -> pb2.SourceDeclared:
    message = pb2.SourceDeclared(source_key=stream.source_key, name=stream.name, client_version=client_version)
    message.tactile.channels.extend(
        pb2.TactileChannelDescriptor(
            key=channel.key,
            label=channel.label,
            sample_format=channel.sample_format,
            sample_count=channel.sample_count,
        )
        for channel in stream.channels
    )
    return message


def _marker_declared(stream: MarkerStreamSchema, client_version: str) -> pb2.SourceDeclared:
    message = pb2.SourceDeclared(source_key=stream.source_key, name=stream.name, client_version=client_version)
    message.marker.CopyFrom(pb2.MarkerSourceDescriptor())
    return message


def _camera_declared(stream: CameraStreamSchema, client_version: str) -> pb2.SourceDeclared:
    message = pb2.SourceDeclared(source_key=stream.source_key, name=stream.name, client_version=client_version)
    message.camera.available_settings.extend(camera_setting_to_pb(setting) for setting in stream.available_settings)
    if stream.rtsp is not None:
        message.camera.rtsp.CopyFrom(rtsp_camera_protocol_to_pb(stream.rtsp))
    if stream.zmq is not None:
        message.camera.zmq.CopyFrom(zmq_camera_protocol_to_pb(stream.zmq))
    return message


def rtsp_camera_protocol_to_pb(protocol: RtspCameraProtocol) -> pb2.RtspCameraProtocol:
    return pb2.RtspCameraProtocol(uri=protocol.uri, transport=_RTSP_TRANSPORT_TO_PB[protocol.transport])


def rtsp_camera_protocol_from_pb(message: pb2.RtspCameraProtocol) -> RtspCameraProtocol:
    return RtspCameraProtocol(
        uri=message.uri,
        transport=_RTSP_TRANSPORT_FROM_PB.get(message.transport, RtspTransport.TCP),
    )


rtsp_camera_endpoint_to_pb = rtsp_camera_protocol_to_pb
rtsp_camera_endpoint_from_pb = rtsp_camera_protocol_from_pb


def zmq_camera_protocol_to_pb(protocol: ZmqCameraProtocol) -> pb2.ZmqCameraProtocol:
    return pb2.ZmqCameraProtocol(
        uri=protocol.uri,
        message_mode=_ZMQ_MESSAGE_MODE_TO_PB[protocol.message_mode],
        frame_encoding=_CAMERA_FRAME_ENCODING_TO_PB[protocol.frame_encoding],
    )


def zmq_camera_protocol_from_pb(message: pb2.ZmqCameraProtocol) -> ZmqCameraProtocol:
    return ZmqCameraProtocol(
        uri=message.uri,
        message_mode=_zmq_message_mode_from_pb(message.message_mode),
        frame_encoding=_camera_frame_encoding_from_pb(message.frame_encoding),
    )


def _zmq_message_mode_from_pb(message_mode: pb2.ZmqMessageMode) -> ZmqMessageMode:
    supported = _ZMQ_MESSAGE_MODE_FROM_PB.get(message_mode)
    if supported is not None:
        return supported
    try:
        name = pb2.ZmqMessageMode.Name(message_mode)
    except ValueError:
        name = str(message_mode)
    raise ValueError(f"unsupported ZMQ camera message_mode {name}; loop-sdk currently supports single_frame only")


def _camera_frame_encoding_from_pb(frame_encoding: pb2.CameraFrameEncoding) -> CameraFrameEncoding:
    supported = _CAMERA_FRAME_ENCODING_FROM_PB.get(frame_encoding)
    if supported is not None:
        return supported
    try:
        name = pb2.CameraFrameEncoding.Name(frame_encoding)
    except ValueError:
        name = str(frame_encoding)
    raise ValueError(f"unsupported camera frame_encoding {name}; loop-sdk currently supports JPEG only")


def camera_setting_to_pb(setting: CameraSetting) -> pb2.CameraSetting:
    return pb2.CameraSetting(
        resolution=pb2.CameraResolution(width=setting.resolution.width, height=setting.resolution.height),
        fps=setting.fps,
        pixel_format=_CAMERA_PIXEL_FORMAT_TO_PB[setting.pixel_format],
        horizontal_flip=setting.horizontal_flip,
        vertical_flip=setting.vertical_flip,
    )


def camera_setting_from_pb(message: pb2.CameraSetting) -> CameraSetting:
    pixel_format = _camera_pixel_format_from_pb(message.pixel_format)
    return CameraSetting(
        resolution=CameraResolution(width=message.resolution.width, height=message.resolution.height),
        fps=message.fps,
        pixel_format=pixel_format,
        horizontal_flip=message.horizontal_flip,
        vertical_flip=message.vertical_flip,
    )


def _camera_pixel_format_from_pb(pixel_format: pb2.CameraPixelFormat) -> CameraPixelFormat:
    supported = _CAMERA_PIXEL_FORMAT_FROM_PB.get(pixel_format)
    if supported is not None:
        return supported
    try:
        name = pb2.CameraPixelFormat.Name(pixel_format)
    except ValueError:
        name = str(pixel_format)
    raise ValueError(f"unsupported camera pixel_format {name}; loop-sdk currently supports MJPEG only")


def camera_open_result_to_pb(result: CameraOpenResult) -> pb2.CameraOpenResult:
    message = pb2.CameraOpenResult()
    if result.applied_setting is not None:
        message.applied_setting.CopyFrom(camera_setting_to_pb(result.applied_setting))
    if result.rtsp is not None:
        message.rtsp.CopyFrom(rtsp_camera_protocol_to_pb(result.rtsp))
    if result.zmq is not None:
        message.zmq.CopyFrom(zmq_camera_protocol_to_pb(result.zmq))
    return message


def sample_batch(frame: FrameSample, session_id: str, source_id: str) -> pb2.SampleBatch:
    """Map one domain frame to a single-sample ``SampleBatch``."""
    return pb2.SampleBatch(
        session_id=session_id,
        source_id=source_id,
        samples=[_sample(frame)],
    )


def _to_pb_robot_value(value: RobotStateValue) -> pb2.RobotValue:
    # bool is a subclass of int, so it must be checked first. None / unknown
    # types yield an empty RobotValue (no arm set) and are filtered before this.
    if isinstance(value, bool):
        return pb2.RobotValue(bool_value=value)
    if isinstance(value, int):
        return pb2.RobotValue(int_value=value)
    if isinstance(value, float):
        return pb2.RobotValue(scalar=value)
    if isinstance(value, str):
        return pb2.RobotValue(string_value=value)
    if isinstance(value, list):
        return pb2.RobotValue(array=pb2.DoubleArray(values=[float(item) for item in value]))
    return pb2.RobotValue()


def _robot_state_value(value: pb2.RobotValue) -> RobotStateValue:
    arm = value.WhichOneof("value")
    if arm == "scalar":
        return value.scalar
    if arm == "array":
        return list(value.array.values)
    if arm == "int_value":
        return value.int_value
    if arm == "bool_value":
        return value.bool_value
    if arm == "string_value":
        return value.string_value
    return None


def _sample(frame: FrameSample) -> pb2.Sample:
    sample = pb2.Sample(timestamp_us=frame.timestamp_us, sequence=frame.sequence)
    if isinstance(frame, RobotFrame):
        for key, value in frame.state.items():
            if value is None:
                continue
            sample.robot.state[key].CopyFrom(_to_pb_robot_value(value))
        return sample
    if isinstance(frame, TactileFrame):
        sample.tactile.channels.extend(
            pb2.TactileChannelSample(key=channel.key, raw=channel.raw, values_i16=channel.values_i16)
            for channel in frame.channels
        )
        return sample
    if isinstance(frame, MarkerFrame):
        sample.marker.CopyFrom(pb2.MarkerPayload(label=frame.label, category=frame.category))
        return sample
    raise TypeError(f"unsupported frame type: {type(frame).__name__}")


def frame_from_sample(source_id: str, sample: pb2.Sample) -> FrameSample:
    """Decode one read-plane ``Sample`` into a domain frame (the inverse of ``_sample``).

    ``Sample`` carries no source identifier (it is per-source on the wire); the
    subscription supplies the runtime ``source_id``.
    """
    payload = sample.WhichOneof("payload")
    if payload == "robot":
        return RobotFrame(
            source_id=source_id,
            timestamp_us=sample.timestamp_us,
            sequence=sample.sequence,
            state={key: _robot_state_value(value) for key, value in sample.robot.state.items()},
        )
    if payload == "tactile":
        return TactileFrame(
            source_id=source_id,
            timestamp_us=sample.timestamp_us,
            sequence=sample.sequence,
            channels=tuple(
                TactileChannelValue(key=channel.key, raw=channel.raw, values_i16=tuple(channel.values_i16))
                for channel in sample.tactile.channels
            ),
        )
    if payload == "marker":
        return MarkerFrame(
            source_id=source_id,
            timestamp_us=sample.timestamp_us,
            sequence=sample.sequence,
            label=sample.marker.label,
            category=sample.marker.category,
        )
    if payload == "policy_action":
        pa = sample.policy_action
        return PolicyActionFrame(
            source_id=source_id,
            timestamp_us=sample.timestamp_us,
            sequence=sample.sequence,
            actions=tuple(tuple(vector.values) for vector in pa.actions),
            input_sample_set_source_id=(
                pa.input_sample_set_source_id if pa.HasField("input_sample_set_source_id") else None
            ),
            input_sample_set_sequence=(
                pa.input_sample_set_sequence if pa.HasField("input_sample_set_sequence") else None
            ),
        )
    raise TypeError(f"sample carries no known payload (oneof={payload!r})")
